/*
 * Is this ALT allele a symbolic structural variant allele whose reference span
 * is given by INFO/SVLEN?  These are the <DEL>, <DUP>, <INV> and <CNV> alleles,
 * whose first level type may be followed by a colon separated list of subtypes
 * (e.g. <DEL:ME> or <CNV:TR>) which does not change the interpretation of the
 * allele.  See sections 1.4.5 and 3 of the VCF specification.
 */
static int svlen_defines_span(const char *alt, size_t len)
{
    static const char types[][4] = { "DEL", "DUP", "INV", "CNV" };
    size_t i, ntypes = sizeof(types) / sizeof(types[0]);

    // Symbolic alleles are enclosed in angle brackets, e.g. "<DEL>"
    if (len < 5 || alt[0] != '<' || alt[len-1] != '>') return 0;
    alt++;
    len -= 2;

    for (i = 0; i < ntypes; i++) {
        if (len < 3 || memcmp(alt, types[i], 3) != 0) continue;
        if (len == 3 || alt[3] == ':') return 1;    // type or type:subtype
    }
    return 0;
}

// See the description in hts_internal.h
hts_pos_t vcf_svlen_ref_span(const char *alt, const char *svlen)
{
    hts_pos_t rlen = 0;

    if (!alt || !svlen) return 0;

    // INFO/SVLEN has one value per ALT allele, in the order of the ALT column
    while (*alt) {
        const char *alt_end = alt;
        while (*alt_end && *alt_end != ',') alt_end++;

        if (svlen_defines_span(alt, alt_end - alt)) {
            char *val_end;
            long long len = strtoll(svlen, &val_end, 10);
            // Missing (".") and malformed values leave the span undefined
            if (val_end != svlen && len != LLONG_MIN) {
                if (len < 0) len = -len;    // a negative SVLEN means |SVLEN|
                // POS is the base immediately preceding the variant, so the
                // record spans POS to POS+SVLEN inclusive.
                if (len < HTS_POS_MAX && len + 1 > rlen) rlen = len + 1;
            }
        }

        if (!*alt_end) break;
        alt = alt_end + 1;

        // Move on to the SVLEN value of the next ALT allele, if there is one
        while (*svlen && *svlen != ',' && *svlen != ';') svlen++;
        if (*svlen != ',') break;
        svlen++;
    }

    return rlen;
}

/*
 * As vcf_svlen_ref_span() above, but for an already parsed record.  Both the
 * alleles and the INFO fields of line must be unpacked (or unpackable).
 */
static hts_pos_t bcf_svlen_ref_span(const bcf_hdr_t *hdr, bcf1_t *line)
{
