/*
 * Recalculate line->rlen, the number of reference bases covered by the record.
 * That is the longest span of its alleles: the length of REF, the deprecated
 * INFO/END and, for symbolic structural variant alleles, POS+SVLEN.
 * Both the alleles and the INFO fields of line must be unpacked (or unpackable).
 */
static void bcf_sync_rlen(const bcf_hdr_t *hdr, bcf1_t *line)
{
    hts_pos_t rlen, svlen_rlen;

    // Note that END is 1-based while line->pos 0-based
    bcf_info_t *end_info = bcf_get_info(hdr,line,"END");
    if ( end_info )
    {
        if ( !end_info->vptr ) end_info = NULL;     // marked for removal
        else if ( end_info->type==BCF_HT_INT && end_info->v1.i==bcf_int32_missing ) end_info = NULL;
        else if ( end_info->type==BCF_HT_LONG && end_info->v1.i==bcf_int64_missing ) end_info = NULL;
    }
    if ( end_info && end_info->v1.i > line->pos )
        rlen = end_info->v1.i - line->pos;
    else if ( line->n_allele > 0 )
        rlen = strlen(line->d.allele[0]);
    else
        rlen = 0;

    // Symbolic structural variant alleles can span more of the reference than
    // REF and the deprecated INFO/END indicate; INFO/SVLEN gives their length.
    svlen_rlen = bcf_svlen_ref_span(hdr, line);
    line->rlen = svlen_rlen > rlen ? svlen_rlen : rlen;
}

static inline int _bcf1_sync_alleles(const bcf_hdr_t *hdr, bcf1_t *line, int nals)
{
    line->d.shared_dirty |= BCF1_DIRTY_ALS;
    line->d.var_type = -1;

    line->n_allele = nals;
    hts_expand(char*, line->n_allele, line->d.m_allele, line->d.allele);

    char *als = line->d.als;
    int n = 0;
    while (n<nals)
    {
        line->d.allele[n] = als;
        while ( *als ) als++;
        als++;
        n++;
    }

    // Update the reference span of the record, which depends on the alleles
    bcf_sync_rlen(hdr, line);

    return 0;
}

