/*
 * Look up an INFO key in a VCF INFO column.  Both the column, which is a list
 * of ';' separated key=value pairs, and the returned value are terminated by
 * ';' or NUL.  Returns NULL if the key is not present.
 */
static const char *vcf_info_value(const char *info, const char *key,
                                 size_t key_len)
{
    const char *s = info;
    for (;;) {
        if (strncmp(s, key, key_len) == 0 && s[key_len] == '=')
            return s + key_len + 1;
        if (!(s = strchr(s, ';'))) return NULL;
        s++;
    }
}

