     static int svlen_defines_span(const char *alt, size_t len)
     {
         static const char types[][4] = { "DEL", "DUP", "INV", "CNV" };
         size_t i, ntypes = sizeof(types) / sizeof(types[0]);

         // Symbolic alleles are enclosed in angle brackets, e.g. "<DEL>"
         if (len < 5 || alt[0] != '<' || alt[len-1] != '>') return 0;
         alt++;
         len -= 2;

         for (i = 0; i < ntypes; i++) {
             if (len < 3 || memcmp(alt, types[i], 3) != 0) continue;
             if (len == 3 || alt[3] == ':') return 1;    // type or type:subtype
         }
         return 0;
     }

     // See the description in hts_internal.h
     hts_pos_t vcf_svlen_ref_span(const char *alt, const char *svlen)
     {
         hts_pos_t rlen = 0;
         if (!alt || !svlen) return 0;
         while (*alt) {
             const char *alt_end = alt;
