/* Print the reference span (rlen) that htslib records for each VCF/BCF record,
   and exercise the bcf_update_info() paths that recompute it. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <htslib/vcf.h>

static void show(const bcf_hdr_t *h, bcf1_t *v, const char *what)
{
    bcf_unpack(v, BCF_UN_INFO);
    printf("%-24s %s\t%"PRIhts_pos"\t%s\trlen=%"PRIhts_pos"\tend=%"PRIhts_pos"\n",
           what, bcf_seqname(h, v), v->pos + 1,
           v->d.id ? v->d.id : ".", v->rlen, v->pos + v->rlen);
}

int main(int argc, char **argv)
{
    htsFile *fp = hts_open(argv[1], "r");
    bcf_hdr_t *h = fp ? bcf_hdr_read(fp) : NULL;
    bcf1_t *v = bcf_init();
    const char *mode = argc > 2 ? argv[2] : "read";
    if (!fp || !h || !v) { fprintf(stderr, "open failed\n"); return 2; }

    while (bcf_read(fp, h, v) == 0) {
        if (!strcmp(mode, "read")) {
            show(h, v, "read");
        } else if (!strcmp(mode, "update")) {
            hts_pos_t original;
            int32_t end;
            show(h, v, "read");
            original = v->rlen;

            /* Re-setting the alleles must not change the span */
            const char *alleles[2];
            bcf_unpack(v, BCF_UN_STR);
            alleles[0] = strdup(v->d.allele[0]);
            alleles[1] = v->n_allele > 1 ? strdup(v->d.allele[1]) : NULL;
            if (bcf_update_alleles(h, v, alleles, v->n_allele > 1 ? 2 : 1) < 0)
                fprintf(stderr, "update_alleles failed\n");
            show(h, v, v->rlen == original || v->n_allele > 2
                        ? "  update_alleles" : "  update_alleles CHANGED");
            free((void *)alleles[0]); free((void *)alleles[1]);

            /* Removing INFO/END must fall back to REF/SVLEN, not to REF alone */
            if (bcf_update_info_int32(h, v, "END", NULL, 0) < 0)
                fprintf(stderr, "END removal failed\n");
            show(h, v, "  END removed");

            /* Adding INFO/END that reaches further must extend the span */
            end = (int32_t)(v->pos + 1 + 4000);
            if (bcf_update_info_int32(h, v, "END", &end, 1) < 0)
                fprintf(stderr, "END add failed\n");
            show(h, v, "  END=pos+4000");

            /* ... and removing it again must return to the SVLEN/REF span */
            if (bcf_update_info_int32(h, v, "END", NULL, 0) < 0)
                fprintf(stderr, "END removal failed\n");
            show(h, v, "  END removed");

            /* Removing INFO/SVLEN leaves only REF (and END, absent here) */
            if (bcf_update_info_int32(h, v, "SVLEN", NULL, 0) < 0)
                fprintf(stderr, "SVLEN removal failed\n");
            show(h, v, "  SVLEN removed");

            /* Adding SVLEN back must restore a symbolic allele's span */
            int32_t svlen[3] = { -321, -321, -321 };
            if (bcf_update_info_int32(h, v, "SVLEN", svlen,
                                      v->n_allele > 1 ? v->n_allele - 1 : 1) < 0)
                fprintf(stderr, "SVLEN add failed\n");
            show(h, v, "  SVLEN=-321");
        }
    }
    bcf_destroy(v); bcf_hdr_destroy(h); hts_close(fp);
    return 0;
}
